import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
import * as d3 from 'd3';
import ts from 'typescript';

// Evaluate only the inspected palette construction blocks, not Anki's UI.
const [checkout, baselinePath, originalPath] = process.argv.slice(2);
const graphDir = `${checkout}/ts/routes/graphs`;
const calendar = fs.readFileSync(`${graphDir}/calendar.ts`, 'utf8');
const baseline = fs.readFileSync(baselinePath, 'utf8');
const original = fs.readFileSync(originalPath, 'utf8');
function scale(source, nightMode, colorBlindMode) {
  const start = source.indexOf('    const cappedRange =', source.indexOf('const data = Array.from(dayMap.values())'));
  const end = source.indexOf('    function tooltipText', start);
  assert(start >= 0 && end > start, 'calendar palette block found');
  const block = source.slice(start, end);
  const name = block.includes('let gradient') ? 'gradient' : 'blues';
  const script = ts.transpileModule(block + `\nresult = ${name};`, {
    compilerOptions: { target: ts.ScriptTarget.ES2022 }
  }).outputText;
  const context = {...d3, nightMode, maxCount: 100, window: {colorBlindMode}};
  vm.runInNewContext(script, context, {timeout: 1000});
  return context.result;
}

let failures = 0;
function test(name, fn) {
  try { fn(); console.log(`PASS ${name}`); }
  catch (e) { failures++; console.log(`FAIL ${name}: ${e.message}`); }
}
for (const night of [false, true]) {
  test(`default calendar matches baseline for all nonempty counts 1..100; night=${night}`, () => {
    const expected = scale(baseline, night, false);
    const actual = scale(calendar, night, false);
    for (let count = 1; count <= 100; count++) {
      assert.equal(actual(count), expected(count), `count=${count}`);
    }
  });
  test(`enabled calendar preserves proposed palette for all counts 0..100; night=${night}`, () => {
    const expected = scale(original, night, true);
    const actual = scale(calendar, night, true);
    for (let count = 0; count <= 100; count++) assert.equal(actual(count), expected(count));
  });
}
const cardSource = fs.readFileSync(`${graphDir}/card-counts.ts`, 'utf8');
const block = cardSource.slice(cardSource.indexOf('let barColours;'), cardSource.indexOf('function countCards'));
assert(block.startsWith('let barColours;'), 'card palette block found');
const helpers = fs.readFileSync(`${graphDir}/graph-helpers.ts`, 'utf8');
const palette = helpers.match(/export const colorBlindColors = (\{[\s\S]*?\});/);
assert(palette, 'proposed palette found');
for (const enabled of [false, true]) {
  test(`all seven card colors parse; enabled=${enabled}`, () => {
    const context = {...d3, window: {colorBlindMode: enabled}};
    const code = `const colorBlindColors = ${palette[1]};\n${block}\nresult = barColours;`;
    vm.runInNewContext(ts.transpileModule(code, {}).outputText, context, {timeout: 1000});
    assert.equal(context.result.length, 7);
    for (const color of context.result) assert(d3.color(color), `invalid color ${color}`);
  });
}
console.log(`${6-failures}/6 checks passed. Scope: palette logic only; no Qt or browser integration.`);
process.exitCode = failures ? 1 : 0;
